  async function pasteCaptureUrl() { const error = document.querySelector('#capture-error'); try { const value = await navigator.clipboard.readText(); if (!value.trim()) throw new Error('剪贴板没有可用链接。'); document.querySelector('#capture-url').value = value.trim(); error.textContent = ''; } catch { error.textContent = '无法读取剪贴板，请手动粘贴 X 链接。'; } }
  function bind() { window.addEventListener('hashchange', render); document.querySelector('#global-search-form')?.addEventListener('submit', (event) => { event.preventDefault(); runGlobalSearch(document.querySelector('#global-search')?.value); }); document.querySelector('#open-capture')?.addEventListener('click', openCaptureDialog); document.querySelector('#open-capture-timeline')?.addEventListener('click', openCaptureDialog); document.querySelector('#paste-capture-url')?.addEventListener('click', () => void pasteCaptureUrl()); document.querySelector('#capture-form')?.addEventListener('submit', submitCapture); document.querySelector('#period-filter')?.addEventListener('change', renderTimeline); document.querySelector('#timeline-search')?.addEventListener('input', renderTimeline); document.querySelector('#timeline-sort')?.addEventListener('change', renderTimeline); document.querySelector('#refresh-timeline')?.addEventListener('click', () => void probeBridge()); document.querySelector('#action-filters')?.addEventListener('click', (event) => { const button = event.target.closest('[data-filter]'); if (!button) return; currentFilter = button.dataset.filter; interestMode = null; renderTimeline(); }); document.querySelector('#interest-insights')?.addEventListener('click', (event) => { const target = event.target.closest('[data-interest-mode]'); if (target) selectInterest(target.dataset.interestMode) }); document.querySelector('#interest-summary')?.addEventListener('click', (event) => { const target = event.target.closest('[data-interest-mode]'); if (target) selectInterest(target.dataset.interestMode) }); document.querySelector('#tag-cloud')?.addEventListener('click', (event) => { const target = event.target.closest('[data-interest-mode]'); if (target) selectInterest(target.dataset.interestMode) }); document.querySelector('#export-data')?.addEventListener('click', downloadExport); document.querySelector('#retry-bridge')?.addEventListener('click', () => void probeBridge()); document.querySelector('#delete-history')?.addEventListener('click', async () => { if (!window.confirm('确定删除当前本地 Capture 历史吗？私人资料库不会被删除。')) return; try { await api('/v1/x/local-capture/history', { method: 'DELETE' }); } catch { state.events = []; state.content = []; saveState(); } await hydrateFromBridge().catch(() => {}); render(); }); ['enabled', 'captureLikes', 'captureBookmarks', 'captureViews', 'captureSharedLinks', 'watchCapture', 'savePageMetadata'].forEach((key) => document.querySelector(`#setting-${key}`)?.addEventListener('change', async (event) => { const patch = { [key]: event.target.checked }; try { state.settings = await api('/v1/x/local-capture/settings', { method: 'PATCH', body: JSON.stringify(patch) }); bridge.connected = true; } catch { state.settings = { ...state.settings, [key]: event.target.checked, updatedAt: new Date().toISOString() }; saveState(); } render(); })); }
  document.querySelector('#timeline-note-form')?.addEventListener('submit', submitTimelineNote);
